insert into public.book_sections (store_id, position, title, blocks) values ((select id from public.stores where slug = 'micheladas'), 0, 'Introducción', '[{"tipo":"p","texto":"Esta guía es para que prepares micheladas y cervezas preparadas en casa para tus propias reuniones: partidos de fútbol, tardes de parche, asados de fin de semana. Cada receta está pensada para que te rinda, se vea bien en las fotos y no te tome mucho tiempo armarla."},{"tipo":"p","texto":"Las recetas sirven para partidos, asados, tardes de parche y reuniones con amigos y familia. Cada una te dice qué dejar listo antes y qué hacer al servir, para que tú también disfrutes la reunión."},{"tipo":"p","texto":"Consumo responsable: la cerveza es alcohol, y estas recetas son solo para personas mayores de 18 años. No sirvas alcohol a menores de edad, no se lo ofrezcas a quien va a manejar después del evento y ten siempre alternativas sin alcohol a la mano: las 3 micheladas sin alcohol de este libro son justo para eso."}]'::jsonb);
insert into public.book_sections (store_id, position, title, blocks) values ((select id from public.stores where slug = 'micheladas'), 1, 'Lo básico de la michelada', '[{"tipo":"p","texto":"Lo que distingue una michelada casera buena no es la cerveza: es el escarchado del borde y la mezcla de salsas. Deja listas estas bases con anticipación y armas cualquier receta de esta guía en minutos:"},{"tipo":"tabla","filas":[["Base de escarchado","Cómo se prepara y para qué sirve"],["Base de chamoy","Mezcla chamoy con un poco de jugo de limón hasta que quede líquido; con eso humedeces el borde del vaso antes de pasarlo por sal o por chile en polvo. Es la base de las micheladas con chamoy, tamarindo y gomitas."],["Base de tajín (sal con chile y limón deshidratado)","Mezcla sal fina con tajín en partes iguales. Es el escarchado más usado en las micheladas con fruta (mango, maracuyá, piña, fresa, sandía)."],["Sal con limón","La combinación más simple: solo sal fina, humedecida con limón. Sirve para la michelada clásica y la chelada."]]},{"tipo":"p","texto":"Guarda cada mezcla seca (tajín, sal) en un frasquito tapado; aguantan varias semanas fuera de la nevera. La base de chamoy líquida se guarda tapada en la nevera y aguanta cerca de 2 semanas."},{"tipo":"p","texto":"Medidas que vas a usar en varias recetas:"},{"tipo":"tabla","filas":[["Medida","Equivalencia en casa"],["1 cerveza clara estándar","330 - 355 ml"],["1 vaso alto (highball) para michelada","400 - 450 ml"],["1 shot","30 ml, aproximadamente 2 cucharadas soperas"]]},{"tipo":"p","texto":"Hielo: usa cubos grandes, no hielo picado, para que la michelada no se aguade rápido y la cerveza mantenga su burbuja."}]'::jsonb);
insert into public.book_sections (store_id, position, title, blocks) values ((select id from public.stores where slug = 'micheladas'), 2, 'Seguridad y consumo responsable', '[{"tipo":"ul","items":["Sirve alcohol solo a personas mayores de 18 años. Si no conoces a todos los invitados, confirma edad antes de ofrecer cerveza.","Ten siempre a la mano las micheladas sin alcohol de este libro, visibles y en la misma mesa, no escondidas.","No le sirvas más a alguien que ya se ve muy afectado; ofrécele agua o comida en su lugar.","Si alguien va a manejar, no le ofrezcas cerveza; ten números de transporte a mano para los invitados.","Guarda la cerveza y las micheladas ya armadas fuera del alcance de niños y adolescentes durante todo el evento.","Lava bien frutas, limones y verduras (pepino, tomate) antes de usarlos, igual que harías para cualquier otra receta."]}]'::jsonb);
insert into public.recipe_categories (store_id, slug, name, description, position) values ((select id from public.stores where slug = 'micheladas'), 'micheladas-para-tus-reuniones', 'Micheladas para tus reuniones', 'Siete formas de darle la vuelta a una cerveza: desde la michelada clásica hasta versiones con fruta, chamoy y gomitas que llaman la atención en redes.', 0) on conflict (store_id, slug) do update set name = excluded.name, description = excluded.description, position = excluded.position;
insert into public.recipe_categories (store_id, slug, name, description, position) values ((select id from public.stores where slug = 'micheladas'), 'micheladas-sin-alcohol', 'Micheladas sin alcohol', 'Para quien no toma, para los conductores de la noche o para servir junto a las micheladas con cerveza sin dejar a nadie sin opción. Cambian la cerveza por soda o malta fría.', 1) on conflict (store_id, slug) do update set name = excluded.name, description = excluded.description, position = excluded.position;
insert into public.recipe_categories (store_id, slug, name, description, position) values ((select id from public.stores where slug = 'micheladas'), 'nuevas-y-cervezas-preparadas', 'Nuevas y cervezas preparadas', 'Doce recetas adicionales para ampliar el menú: micheladas con sabores nuevos, formatos para llevar y clásicos colombianos que no son michelada pero se sirven igual de fríos.', 2) on conflict (store_id, slug) do update set name = excluded.name, description = excluded.description, position = excluded.position;
insert into public.recipes (store_id, category_id, slug, title, position, photo_path, photo_people_path, yield_text, yield_servings, time_text, ingredients, steps, notes, extras) values ((select id from public.stores where slug = 'micheladas'), (select id from public.recipe_categories where store_id = (select id from public.stores where slug = 'micheladas') and slug = 'micheladas-para-tus-reuniones'), 'michelada-clasica', 'Michelada clásica', 0, 'micheladas/foto-michelada-clasica.jpg', 'micheladas/gente-michelada-clasica.jpg', '1 vaso alto (400 ml)', 1, '5 minutos', '[{"raw":"1 cerveza clara bien fría (330 - 355 ml)","qty":1,"rest":"cerveza clara bien fría (330 - 355 ml)"},{"raw":"15 ml de jugo de limón","qty":15,"rest":"ml de jugo de limón"},{"raw":"5 ml de salsa inglesa (Worcestershire)","qty":5,"rest":"ml de salsa inglesa (Worcestershire)"},{"raw":"Unas gotas de salsa picante","qty":null,"rest":"Unas gotas de salsa picante"},{"raw":"Sal y chile en polvo para el borde","qty":null,"rest":"Sal y chile en polvo para el borde"},{"raw":"Hielo en cubos","qty":null,"rest":"Hielo en cubos"}]'::jsonb, '["Humedece el borde del vaso con limón y pásalo por una mezcla de sal y chile en polvo.","Llena el vaso con hielo.","Agrega el jugo de limón, la salsa inglesa y la salsa picante.","Completa con la cerveza, dejándola caer despacio para que no se vaya toda en espuma.","Nota: si quieres la versión chelada (la más simple de todas), omite la salsa inglesa y la picante y usa solo limón y sal; es la que más rápido armas cuando hay prisa."]'::jsonb, '[]'::jsonb, '{"adelanta":"La mezcla de limón, salsa picante y salsa inglesa se puede premedir en frasquitos individuales desde el día anterior. El escarchado de sal y chile en el borde también se prepara antes.","presentacion":"Vaso alto con el borde escarchado de sal y chile; se sirve con la botella al lado para que cada quien rellene.","conservacion":"Se toma de inmediato apenas se abre la cerveza.","variacion":"Cambia la cerveza por soda o agua mineral con el mismo escarchado: versión sin alcohol en la sección de micheladas sin alcohol de esta guía.","variacion_titulo":"Sin alcohol"}'::jsonb) on conflict (store_id, slug) do update set category_id = excluded.category_id, title = excluded.title, position = excluded.position, photo_path = excluded.photo_path, photo_people_path = excluded.photo_people_path, yield_text = excluded.yield_text, yield_servings = excluded.yield_servings, time_text = excluded.time_text, ingredients = excluded.ingredients, steps = excluded.steps, notes = excluded.notes, extras = excluded.extras;
insert into public.recipes (store_id, category_id, slug, title, position, photo_path, photo_people_path, yield_text, yield_servings, time_text, ingredients, steps, notes, extras) values ((select id from public.stores where slug = 'micheladas'), (select id from public.recipe_categories where store_id = (select id from public.stores where slug = 'micheladas') and slug = 'micheladas-para-tus-reuniones'), 'michelada-cubana', 'Michelada cubana', 1, 'micheladas/foto-michelada-cubana.jpg', 'micheladas/gente-michelada-cubana.jpg', '1 vaso alto (400 ml)', 1, '6 minutos', '[{"raw":"1 cerveza clara bien fría","qty":1,"rest":"cerveza clara bien fría"},{"raw":"100 ml de jugo de tomate o clamato","qty":100,"rest":"ml de jugo de tomate o clamato"},{"raw":"15 ml de jugo de limón","qty":15,"rest":"ml de jugo de limón"},{"raw":"Salsa picante y salsa inglesa al gusto","qty":null,"rest":"Salsa picante y salsa inglesa al gusto"},{"raw":"Sal y pimienta para el borde","qty":null,"rest":"Sal y pimienta para el borde"},{"raw":"Hielo en cubos","qty":null,"rest":"Hielo en cubos"}]'::jsonb, '["Humedece el borde del vaso y pásalo por sal con pimienta.","Llena el vaso con hielo.","Agrega el jugo de tomate, el jugo de limón, la salsa picante y la salsa inglesa.","Completa con la cerveza despacio y revuelve una vez."]'::jsonb, '[]'::jsonb, '{"adelanta":"La mezcla de jugo de tomate (o clamato), salsa inglesa y salsa picante se puede premedir en frasquitos desde el día anterior para armar más rápido durante el evento.","presentacion":"Vaso alto con borde de sal y pimienta; puedes agregar un tallo de apio como garnish si tienes.","conservacion":"Se toma de inmediato apenas se abre la cerveza."}'::jsonb) on conflict (store_id, slug) do update set category_id = excluded.category_id, title = excluded.title, position = excluded.position, photo_path = excluded.photo_path, photo_people_path = excluded.photo_people_path, yield_text = excluded.yield_text, yield_servings = excluded.yield_servings, time_text = excluded.time_text, ingredients = excluded.ingredients, steps = excluded.steps, notes = excluded.notes, extras = excluded.extras;
insert into public.recipes (store_id, category_id, slug, title, position, photo_path, photo_people_path, yield_text, yield_servings, time_text, ingredients, steps, notes, extras) values ((select id from public.stores where slug = 'micheladas'), (select id from public.recipe_categories where store_id = (select id from public.stores where slug = 'micheladas') and slug = 'micheladas-para-tus-reuniones'), 'michelada-chilena', 'Michelada chilena', 2, 'micheladas/foto-michelada-chilena.jpg', 'micheladas/gente-michelada-chilena.jpg', '1 vaso alto (400 ml)', 1, '5 minutos', '[{"raw":"1 cerveza lager bien fría","qty":1,"rest":"cerveza lager bien fría"},{"raw":"15 ml de jugo de limón","qty":15,"rest":"ml de jugo de limón"},{"raw":"5 ml de salsa inglesa (Worcestershire)","qty":5,"rest":"ml de salsa inglesa (Worcestershire)"},{"raw":"Unas gotas de salsa picante (tipo tabasco)","qty":null,"rest":"Unas gotas de salsa picante (tipo tabasco)"},{"raw":"Sal y pimienta para el borde","qty":null,"rest":"Sal y pimienta para el borde"},{"raw":"Hielo en cubos","qty":null,"rest":"Hielo en cubos"}]'::jsonb, '["Humedece el borde del vaso con limón y pásalo por sal con pimienta.","Llena el vaso con hielo.","Agrega el jugo de limón, la salsa inglesa y la salsa picante.","Completa con la cerveza despacio."]'::jsonb, '[]'::jsonb, '{"adelanta":"La mezcla de limón, salsa inglesa y picante se puede premedir desde el día anterior; el escarchado de sal y pimienta también.","presentacion":"Vaso alto con borde de sal y pimienta, sin más adornos: es una michelada sencilla y directa.","conservacion":"Se toma de inmediato apenas se abre la cerveza."}'::jsonb) on conflict (store_id, slug) do update set category_id = excluded.category_id, title = excluded.title, position = excluded.position, photo_path = excluded.photo_path, photo_people_path = excluded.photo_people_path, yield_text = excluded.yield_text, yield_servings = excluded.yield_servings, time_text = excluded.time_text, ingredients = excluded.ingred