insert into public.recipes (store_id, category_id, slug, title, position, photo_path, photo_people_path, yield_text, yield_servings, time_text, ingredients, steps, notes, extras) values ((select id from public.stores where slug = 'micheladas'), (select id from public.recipe_categories where store_id = (select id from public.stores where slug = 'micheladas') and slug = 'micheladas-para-tus-reuniones'), 'michelada-de-mango', 'Michelada de mango', 3, 'micheladas/foto-michelada-de-mango.jpg', 'micheladas/gente-michelada-de-mango.jpg', '1 vaso alto (400 ml)', 1, '8 minutos', '[{"raw":"1 cerveza clara bien fría","qty":1,"rest":"cerveza clara bien fría"},{"raw":"100 g de pulpa de mango maduro licuada y colada","qty":100,"rest":"g de pulpa de mango maduro licuada y colada"},{"raw":"15 ml de jugo de limón","qty":15,"rest":"ml de jugo de limón"},{"raw":"Sal y chile en polvo para el borde","qty":null,"rest":"Sal y chile en polvo para el borde"},{"raw":"Hielo en cubos","qty":null,"rest":"Hielo en cubos"}]'::jsonb, '["Humedece el borde del vaso y pásalo por sal con chile en polvo.","Llena el vaso con hielo.","Agrega la pulpa de mango y el jugo de limón.","Completa con la cerveza despacio y revuelve una vez."]'::jsonb, '[]'::jsonb, '{"adelanta":"La pulpa de mango se licua y cuela hasta 2 días antes y se guarda en la nevera.","presentacion":"Vaso alto con borde escarchado; una tajada fina de mango en el borde.","conservacion":"Se toma de inmediato apenas se abre la cerveza."}'::jsonb) on conflict (store_id, slug) do update set category_id = excluded.category_id, title = excluded.title, position = excluded.position, photo_path = excluded.photo_path, photo_people_path = excluded.photo_people_path, yield_text = excluded.yield_text, yield_servings = excluded.yield_servings, time_text = excluded.time_text, ingredients = excluded.ingredients, steps = excluded.steps, notes = excluded.notes, extras = excluded.extras;
