insert into public.recipes (store_id, category_id, slug, title, position, photo_path, photo_people_path, yield_text, yield_servings, time_text, ingredients, steps, notes, extras) values ((select id from public.stores where slug = 'micheladas'), (select id from public.recipe_categories where store_id = (select id from public.stores where slug = 'micheladas') and slug = 'micheladas-para-tus-reuniones'), 'gomichela', 'Gomichela', 5, 'micheladas/foto-gomichela.jpg', 'micheladas/gente-gomichela.jpg', '1 vaso alto (450 ml)', 1, '10 minutos', '[{"raw":"1 cerveza clara bien fría","qty":1,"rest":"cerveza clara bien fría"},{"raw":"20 ml de chamoy","qty":20,"rest":"ml de chamoy"},{"raw":"10 ml de salsa picante tipo valentina","qty":10,"rest":"ml de salsa picante tipo valentina"},{"raw":"15 ml de jugo de limón","qty":15,"rest":"ml de jugo de limón"},{"raw":"Sal y chile en polvo para el borde","qty":null,"rest":"Sal y chile en polvo para el borde"},{"raw":"Un puñado de gomitas variadas (ositos, aros, dulces ácidos)","qty":null,"rest":"Un puñado de gomitas variadas (ositos, aros, dulces ácidos)"},{"raw":"Hielo en cubos","qty":null,"rest":"Hielo en cubos"}]'::jsonb, '["Humedece el borde del vaso con chamoy y pásalo por sal con chile en polvo.","Agrega el chamoy, la salsa picante y el jugo de limón al fondo del vaso.","Llena con hielo y completa con la cerveza despacio.","Decora encima con las gomitas, pegándolas en el borde o dejándolas caer sobre el hielo."]'::jsonb, '[]'::jsonb, '{"adelanta":"El chamoy y la salsa picante se pueden premedir en frasquitos desde el día anterior; las gomitas se escogen y separan con anticipación.","presentacion":"Vaso alto con el borde cubierto de chamoy, sal y chile; las gomitas se ven desde afuera.","conservacion":"Se toma de inmediato apenas se abre la cerveza."}'::jsonb) on conflict (store_id, slug) do update set category_id = excluded.category_id, title = excluded.title, position = excluded.position, photo_path = excluded.photo_path, photo_peop