insert into public.recipes (store_id, category_id, slug, title, position, photo_path, photo_people_path, yield_text, yield_servings, time_text, ingredients, steps, notes, extras) values ((select id from public.stores where slug = 'micheladas'), (select id from public.recipe_categories where store_id = (select id from public.stores where slug = 'micheladas') and slug = 'micheladas-para-tus-reuniones'), 'chamochela', 'Chamochela', 6, 'micheladas/foto-chamochela.jpg', 'micheladas/gente-chamochela.jpg', '1 vaso alto (400 ml)', 1, '7 minutos', '[{"raw":"1 cerveza clara bien fría","qty":1,"rest":"cerveza clara bien fría"},{"raw":"25 ml de chamoy","qty":25,"rest":"ml de chamoy"},{"raw":"15 ml de jugo de limón","qty":15,"rest":"ml de jugo de limón"},{"raw":"Sal y chile en polvo para el borde","qty":null,"rest":"Sal y chile en polvo para el borde"},{"raw":"Hielo en cubos","qty":null,"rest":"Hielo en cubos"},{"raw":"1 banderilla de dulce de tamarindo o chile para decorar (opcional)","qty":1,"rest":"banderilla de dulce de tamarindo o chile para decorar (opcional)"}]'::jsonb, '["Humedece el borde del vaso con chamoy y pásalo por sal con chile en polvo.","Agrega el chamoy y el jugo de limón al fondo del vaso.","Llena con hielo y completa con la cerveza despacio.","Decora con la banderilla de tamarindo atravesada en el borde, si tienes."]'::jsonb, '[]'::jsonb, '{"adelanta":"El chamoy y la mezcla de sal con chile para el borde se pueden premedir desde el día anterior.","presentacion":"Vaso alto con el borde de chamoy, sal y chile; se nota el color rojizo del chamoy en el fondo.","conservacion":"Se toma de inmediato apenas se abre la cerveza."}'::jsonb) on conflict (store_id, slug) do update set category_id = excluded.category_id, title = excluded.title, position = excluded.position, photo_path = excluded.photo_path, photo_people_path = excluded.photo_people_path, yield_text = excluded.yield_text, yield_servings = excluded.yield_servings, time_text = excluded.time_text, ingredients = excluded.ingredients, steps = excluded.steps, notes = excluded.notes, extras = excluded.extras;
insert into public.recipes (store_id, category_id, slug, title, position, photo_path, photo_people_path, yield_text, yield_servings, time_text, ingredients, steps, notes, extras) values ((select id from public.stores where slug = 'micheladas'), (select id from public.recipe_categories where store_id = (select id from public.stores where slug = 'micheladas') and slug = 'micheladas-sin-alcohol'), 'michelada-sin-alcohol-clasica', 'Michelada sin alcohol clásica', 7, 'micheladas/foto-michelada-sin-alcohol-clasica.jpg', 'micheladas/gente-michelada-sin-alcohol-clasica.jpg', '4 vasos (350 ml)', 4, '10 min', '[{"raw":"1 taza de jugo de limón colado","qty":1,"rest":"taza de jugo de limón colado"},{"raw":"4 cucharaditas de salsa inglesa (worcestershire)","qty":4,"rest":"cucharaditas de salsa inglesa (worcestershire)"},{"raw":"Unas gotas de salsa picante al gusto","qty":null,"rest":"Unas gotas de salsa picante al gusto"},{"raw":"Sal y chile en polvo para escarchar el borde","qty":null,"rest":"Sal y chile en polvo para escarchar el borde"},{"raw":"2 tazas de soda o malta fría sin alcohol","qty":2,"rest":"tazas de soda o malta fría sin alcohol"}]'::jsonb, '["Escarcha el borde del vaso humedeciéndolo con limón y pasándolo por una mezcla de sal y chile en polvo.","Mezcla el jugo de limón, la salsa inglesa y la salsa picante en un recipiente aparte.","Llena el vaso con hielo y agrega la mezcla de limón.","Termina de llenar con soda o malta fría sin alcohol y revuelve suave."]'::jsonb, '[]'::jsonb, '{"adelanta":"La mezcla de limón, salsa inglesa y picante se puede preparar desde la mañana y guardar en la nevera. El escarchado de sal y chile en el borde también se deja listo antes.","presentacion":"Vaso ancho con el borde escarchado en sal y chile, rodaja de limón en el borde.","conservacion":"Se sirve de inmediato. La mezcla de limón y salsas sin la soda dura 2 días en la nevera.","variacion":"Para la versión con cerveza, cambia la soda sin alcohol por cerveza clara bien fría: consulta la sección de micheladas para tus reuniones de esta misma guía.","variacion_titulo":"Sin alcohol"}'::jsonb) on conflict (store_id, slug) do update set category_id = excluded.category_id, title = excluded.title, position = excluded.position, photo_path = excluded.photo_path, photo_people_path = excluded.photo_people_path, yield_text = excluded.yield_text, yield_servings = excluded.yield_servings, time_text = excluded.time_text, ingredients = excluded.ingredients, steps = excluded.steps, notes = excluded.notes, extras = excluded.extras;
insert into public.recipes (store_id, category_id, slug, title, position, photo_path, photo_people_path, yield_text, yield_servings, time_text, ingredients, steps, notes, extras) values ((select id from public.stores where slug = 'micheladas'), (select id from public.recipe_categories where store_id = (select id from public.stores where slug = 'micheladas') and slug = 'micheladas-sin-alcohol'), 'michelada-de-maracuya-sin-alcohol', 'Michelada de maracuyá sin alcohol', 8, 'micheladas/foto-michelada-de-maracuya-sin-alcohol.jpg', 'micheladas/gente-michelada-de-maracuya-sin-alcohol.jpg', '4 vasos (350 ml)', 4, '10 min', '[{"raw":"1/2 taza de pulpa de maracuyá colada","qty":0.5,"rest":"taza de pulpa de maracuyá colada"},{"raw":"1/2 taza de jugo de limón colado","qty":0.5,"rest":"taza de jugo de limón colado"},{"raw":"3 cucharaditas de salsa inglesa","qty":3,"rest":"cucharaditas de salsa inglesa"},{"raw":"Sal y chile en polvo para escarchar el borde","qty":null,"rest":"Sal y chile en polvo para escarchar el borde"},{"raw":"2 tazas de soda o malta fría sin alcohol","qty":2,"rest":"tazas de soda o malta fría sin alcohol"}]'::jsonb, '["Escarcha el borde del vaso con sal y chile en polvo.","Mezcla la pulpa de maracuyá, el jugo de limón y la salsa inglesa.","Llena el vaso con hielo y agrega la mezcla.","Completa con soda o malta fría sin alcohol."]'::jsonb, '[]'::jsonb, '{"adelanta":"La pulpa de maracuyá colada y la mezcla de limón y salsas se dejan listas en la nevera desde la mañana.","presentacion":"Vaso ancho escarchado, rodaja de maracuyá con cáscara en el borde.","conservacion":"Se sirve de inmediato. La mezcla sin soda dura 2 días en la nevera.","variacion":"Para la versión con cerveza, cambia la soda sin alcohol por cerveza clara: consulta la receta de michelada de maracuyá con cerveza de esta misma guía.","variacion_titulo":"Sin alcohol"}'::jsonb) on conflict (store_id, slug) do update set category_id = excluded.category_id, title = excluded.title, position = excluded.